#pragma once
#include <vector>
#include <algorithm>
#include <string>
namespace PageOrder {
inline std::vector<int> normalized(std::vector<int> selected,int count){selected.erase(std::remove_if(selected.begin(),selected.end(),[&](int x){return x<0||x>=count;}),selected.end());std::sort(selected.begin(),selected.end());selected.erase(std::unique(selected.begin(),selected.end()),selected.end());return selected;}
template<class C>bool parseRange(const std::basic_string<C>&text,int count,std::vector<int>&result){result.clear();if(count<1)return false;auto space=[](C c){return c==' '||c=='\t'||c=='\n'||c=='\r'||c=='\v'||c=='\f';};auto delimiter=[&](C c){return space(c)||c==','||c==';';};if(std::all_of(text.begin(),text.end(),space)){for(int i=1;i<=count;i++)result.push_back(i);return true;}std::vector<bool>seen((size_t)count+1,false);size_t at=0;auto number=[&](int&value){value=0;size_t start=at;while(at<text.size()&&text[at]>='0'&&text[at]<='9'){int digit=text[at++]-'0';if(value>(count-digit)/10)return false;value=value*10+digit;if(value>count)return false;}return at>start&&value>=1;};while(at<text.size()){while(at<text.size()&&delimiter(text[at]))at++;if(at==text.size())break;int first,last;if(!number(first))return false;last=first;if(at<text.size()&&text[at]=='-'){at++;if(!number(last))return false;}if(first>last||(at<text.size()&&!delimiter(text[at])))return false;for(int n=first;n<=last;n++)if(!seen[n]){result.push_back(n);seen[n]=true;}}return !result.empty();}
template<class T>std::vector<int> move(std::vector<T>&items,std::vector<int> selected,int before){selected=normalized(selected,(int)items.size());if(selected.empty())return selected;before=std::max(0,std::min((int)items.size(),before));std::vector<T>keep,moved;int removedBefore=0;for(int i=0;i<(int)items.size();i++)if(std::binary_search(selected.begin(),selected.end(),i)){moved.push_back(items[i]);if(i<before)removedBefore++;}else keep.push_back(items[i]);int at=before-removedBefore;keep.insert(keep.begin()+at,moved.begin(),moved.end());items.swap(keep);std::vector<int>result;for(int i=0;i<(int)moved.size();i++)result.push_back(at+i);return result;}
template<class T>std::vector<int> nudge(std::vector<T>&items,std::vector<int> selected,int direction){selected=normalized(selected,(int)items.size());std::vector<bool>chosen(items.size(),false);for(int i:selected)chosen[i]=true;if(direction<0){for(int i=1;i<(int)items.size();i++)if(chosen[i]&&!chosen[i-1]){std::swap(items[i],items[i-1]);chosen[i-1]=true;chosen[i]=false;}}else{for(int i=(int)items.size()-2;i>=0;i--)if(chosen[i]&&!chosen[i+1]){std::swap(items[i],items[i+1]);chosen[i+1]=true;chosen[i]=false;}}selected.clear();for(int i=0;i<(int)chosen.size();i++)if(chosen[i])selected.push_back(i);return selected;}
}
